# Basic connection
# -------------------------------------------------------------------
listen_addresses = '*'
port = 5432
max_connections = 100

# -------------------------------------------------------------------
# Memory baseline for local lab
# Do not copy blindly to production.
# -------------------------------------------------------------------
shared_buffers = '512MB'
effective_cache_size = '2GB'
work_mem = '16MB'
maintenance_work_mem = '256MB'

# -------------------------------------------------------------------
# WAL and checkpoint visibility
# -------------------------------------------------------------------
wal_level = replica
max_wal_size = '2GB'
min_wal_size = '256MB'
checkpoint_timeout = '10min'
checkpoint_completion_target = 0.9

# -------------------------------------------------------------------
# Logging for learning
# -------------------------------------------------------------------
logging_collector = on
log_destination = 'stderr'
log_directory = 'log'
log_filename = 'postgresql-%Y-%m-%d_%H%M%S.log'
log_min_duration_statement = 250
log_lock_waits = on
deadlock_timeout = '1s'
log_checkpoints = on
log_temp_files = 0
log_autovacuum_min_duration = 0

# -------------------------------------------------------------------
# Query identity and statement statistics
# -------------------------------------------------------------------
compute_query_id = on
shared_preload_libraries = 'pg_stat_statements'
pg_stat_statements.max = 10000
pg_stat_statements.track = all
pg_stat_statements.track_planning = on

# -------------------------------------------------------------------
# Autovacuum visible enough for experiments
# -------------------------------------------------------------------
autovacuum = on
track_io_timing = on
track_wal_io_timing = on
track_functions = pl

# -------------------------------------------------------------------
# Local lab convenience
# -------------------------------------------------------------------
timezone = 'UTC'
lc_messages = 'C'
